#version 330
in vec2 fragTexCoord; out vec4 finalColor;
uniform vec2 resolution; uniform float time; uniform float fade; uniform float fadeTarget;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5);}
float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1)),f.x),f.y);}
float fb(vec2 p){float v=0.,a=.5;for(int i=0;i<4;i++){v+=a*n(p);p=p*2.02+13.;a*=.5;}return v;}
float seg(vec2 p,vec2 a,vec2 b,float w){vec2 q=p-a,d=b-a;return 1.-smoothstep(w,w+.008,length(q-d*clamp(dot(q,d)/dot(d,d),0.,1.)));}
float tree(vec2 q,float s,float seed,float sway){float trunk=seg(q,vec2(0.,-.52*s),vec2(.015*s,.18*s),.035*s)+seg(q,vec2(.01*s,-.02*s),vec2(-.13*s,.13*s),.022*s)+seg(q,vec2(.01*s,.08*s),vec2(.14*s,.27*s),.018*s);float crown=0.;for(int i=0;i<5;i++){float fi=float(i);float x=(h(vec2(seed,fi))-.5)*.28*s+sway*(fi*.13);float y=.18*s+fi*.13*s;float rr=(.16+.07*h(vec2(seed+4.,fi)))*s;crown=max(crown,1.-smoothstep(rr,rr+.018*s,length(q-vec2(x,y))));}return max(trunk,crown);}
float layer(vec2 p,float base,float spacing,float size,float drift,float seed){float x=p.x+time*drift,id=floor(x/spacing),lx=mod(x,spacing)-spacing*.5;float rr=h(vec2(id,seed));return tree(vec2(lx,p.y-base),size*(.78+.5*rr),rr*9.+seed,.018*sin(time*.22+id+seed));}
void main(){vec2 p=(gl_FragCoord.xy-.5*resolution)/resolution.y;float y=p.y+.5;vec3 col=mix(vec3(.25,.025,.045),vec3(.055,.012,.028),smoothstep(.05,1.,y));col+=vec3(.35,.035,.035)*exp(-abs(y-.52)*8.);vec2 moonP=vec2(.31,.28);float moon=1.-smoothstep(.10,.112,length(p-moonP));col+=moon*vec3(.75,.24,.18);float far=smoothstep(.01,-.01,p.y-(-.02+.23*fb(vec2(p.x*.7,2.))));col=mix(col,vec3(.18,.035,.055),far);float ridge=smoothstep(.01,-.01,p.y-(-.17+.18*fb(vec2(p.x*1.2,7.))));col=mix(col,vec3(.12,.026,.043),ridge);float a=layer(p,-.20,.13,.28,.003,11.);col=mix(col,vec3(.22,.045,.055),a*.7);float b=layer(p,-.34,.17,.42,.007,29.);col=mix(col,vec3(.15,.032,.042),b*.82);float c=layer(p,-.53,.25,.64,.012,61.);col=mix(col,vec3(.085,.022,.030),c*.9);float fog=fb(vec2(p.x*1.5-time*.012,p.y*3.+9.));float fogA=exp(-28.*abs(p.y+.16+.035*sin(p.x*2.4-time*.04)))+.7*exp(-34.*abs(p.y+.34+.025*sin(p.x*3.)));col=mix(col,vec3(.38,.10,.10),fogA*(.18+.16*fog));col*=.88+.12*smoothstep(1.2,.25,length(p*vec2(.78,1.)));float f=clamp(fade,0.,1.);finalColor=vec4(mix(vec3(fadeTarget),col,f),1.);}
